var createServerOptions = (dependencies) => ({
  routes: {
    "/health/live": new Response("ok", { headers: { "content-type": "text/plain" } }),
    "/health/ready": async () => await dependencies.readiness() ? Response.json({ status: "ready" }) : Response.json({ status: "not-ready" }, { status: 503 }),
    "/openapi.json": () => Response.json(openApiDocument),
    "/docs": new Response(docsHtml, { headers: { "content-type": "text/html; charset=utf-8" } }),
    "/docs/swagger-ui.css": swaggerCssResponse,
    "/docs/swagger-ui.js": swaggerJavaScriptResponse,
    "/v1/capabilities": () => Response.json({
      apiStyle: "agent-first",
      amountLanguage: "canonical unsigned decimal string; no signs, exponent notation, separators, or leading zeroes",
      tradingEndpoint: "POST /v1/trading",
      actions: ["createOrder", "amendOrder", "cancelOrders", "executeOrder", "batch", "query", "manageWrappedNative"],
      orderKinds: ["market", "limit", "stopMarket", "stopLimit", "trailingStop", "takeProfitMarket", "takeProfitLimit", "oco", "bracket"],
      timeInForce: ["gtc", "gtd", "ioc", "fok"],
      fillPolicies: ["partial", "allOrNone"],
      postPolicies: ["normal", "postOnly", "bookOrCancel"],
      defaults: { marketTimeInForce: "ioc", slippageBps: "50", restingTimeInForce: "gtc", fillPolicy: "partial", postPolicy: "normal" },
      authorizationProfile: "aqua-intent-v1 challenge/retry; not x402 payment",
      chainSelection: "deployment-configured; chainId is never accepted in request bodies",
      erc20Monitoring: {
        transport: "minute polling; no websocket",
        initialLookbackSeconds: 60,
        classifications: ["buy", "sell", "sent", "received", "minted", "burned", "selfTransfer"],
        buySellPolicy: "inferred only from opposite ERC-20 counterflows in the same transaction"
      }
    }),
    "/v1/auth/challenges": {
      POST: (request) => execute(request, async () => {
        const input2 = challengeRequestSchema.parse(await parseJson(request));
        return Response.json(await dependencies.auth.challenge(input2.address), { status: 201 });
      }, dependencies.corsOrigin)
    },
    "/v1/erc20-monitor/subscriptions": {
      GET: (request) => execute(request, async () => {
        const principal2 = await bearer(request, dependencies.auth);
        requireScope(principal2, "activity:read");
        return Response.json({ subscriptions: await dependencies.activity.listSubscriptions(principal2) });
      }, dependencies.corsOrigin),
      POST: (request) => execute(request, async () => {
        const principal2 = await bearer(request, dependencies.auth);
        requireScope(principal2, "activity:write");
        const input2 = subscriptionRequestSchema.parse(await parseJson(request));
        return Response.json(await dependencies.activity.subscribe(input2.address, principal2));
      }, dependencies.corsOrigin)
    },
    "/v1/erc20-monitor/subscriptions/:address": {
      DELETE: (request) => execute(request, async () => {
        const principal2 = await bearer(request, dependencies.auth);
        requireScope(principal2, "activity:write");
        const address = addressSchema.parse(request.params["address"]);
        return Response.json({ removed: await dependencies.activity.unsubscribe(address, principal2) });
      }, dependencies.corsOrigin)
    },
    "/v1/erc20-monitor/actions": {
      GET: (request) => execute(request, async () => {
        const principal2 = await bearer(request, dependencies.auth);
        requireScope(principal2, "activity:read");
        return Response.json(await dependencies.activity.listActions(parseActivityQuery(request), principal2));
      }, dependencies.corsOrigin)
    },
    "/v1/erc20-monitor/actions/wipe": {
      POST: (request) => execute(request, async () => {
        const principal2 = await bearer(request, dependencies.auth);
        requireScope(principal2, "activity:write");
        const input2 = activityWipeSchema.parse(await parseJson(request));
        return Response.json({ deletedCount: (await dependencies.activity.wipe(input2, principal2)).toString(10) });
      }, dependencies.corsOrigin)
    },
    "/v1/auth/sessions": {
      POST: (request) => execute(request, async () => {
        const input2 = sessionRequestSchema.parse(await parseJson(request));
        const result = await dependencies.auth.session(input2.challengeId, input2.message, input2.signature);
        const response = Response.json({ accessToken: result.accessToken, expiresIn: result.expiresIn });
        response.headers.append("set-cookie", `refresh_token=${result.refreshToken}; HttpOnly; Secure; SameSite=Strict; Path=/v1/auth; Max-Age=2592000`);
        return response;
      }, dependencies.corsOrigin)
    },
    "/v1/auth/refresh": {
      POST: (request) => execute(request, async () => {
        const refreshToken = cookie(request, "refresh_token");
        if (refreshToken === null)
          throw new AppError(401, "urn:aqua:error:refresh", "Refresh cookie is required");
        const result = await dependencies.auth.refresh(refreshToken);
        const response = Response.json({ accessToken: result.accessToken, expiresIn: result.expiresIn });
        response.headers.append("set-cookie", `refresh_token=${result.refreshToken}; HttpOnly; Secure; SameSite=Strict; Path=/v1/auth; Max-Age=2592000`);
        return response;
      }, dependencies.corsOrigin)
    },
    "/v1/trading": {
      POST: (request) => execute(request, async () => {
        const input2 = tradingRequestSchema.parse(await parseJson(request));
        const result = await dependencies.trading.execute(input2, await optionalBearer(request, dependencies.auth), request.headers.get("aqua-authorization"));
        const response = Response.json(result.body, { status: result.status });
        if (result.headers !== undefined)
          for (const [name, value] of Object.entries(result.headers))
            response.headers.set(name, value);
        return response;
      }, dependencies.corsOrigin)
    }
  },
  fetch(request) {
    const path = new URL(request.url).pathname;
    const getPaths = new Set(["/health/live", "/health/ready", "/openapi.json", "/docs", "/docs/swagger-ui.css", "/docs/swagger-ui.js", "/v1/capabilities", "/v1/erc20-monitor/subscriptions", "/v1/erc20-monitor/actions"]);
    const postPaths = new Set(["/v1/auth/challenges", "/v1/auth/sessions", "/v1/auth/refresh", "/v1/trading", "/v1/erc20-monitor/subscriptions", "/v1/erc20-monitor/actions/wipe"]);
    if (/^\/v1\/erc20-monitor\/subscriptions\/0x[0-9a-fA-F]{40}$/u.test(path)) {
      const response = problem(405, "urn:aqua:error:method", "Method is not allowed for this route", requestId(request));
      response.headers.set("allow", "DELETE");
      return response;
    }
    if (getPaths.has(path) || postPaths.has(path)) {
      const response = problem(405, "urn:aqua:error:method", "Method is not allowed for this route", requestId(request));
      response.headers.set("allow", getPaths.has(path) && postPaths.has(path) ? "GET, POST" : getPaths.has(path) ? "GET" : "POST");
      return response;
    }
    return problem(404, "urn:aqua:error:not-found", "Route not found", requestId(request));
  },
  error(error61) {
    console.error(JSON.stringify({ level: "error", message: error61.message }));
    return problem(500, "urn:aqua:error:internal", "Unexpected server error", crypto.randomUUID());
  }
});

// apps/api/src/config.ts
var authUriSchema2 = exports_external.url().refine((value) => {
  const url2 = new URL(value);
  return (url2.protocol === "http:" || url2.protocol === "https:") && url2.hash === "";
}, "Expected an absolute, fragment-free HTTP(S) URI");
var pasetoPublicKeySchema = exports_external.string().regex(/^k4\.public\.[A-Za-z0-9_-]{43}$/u);
var environmentSchema = exports_external.object({
  CHAIN_ID: exports_external.coerce.number().int().positive(),
  RPC_URL: exports_external.url(),
  AQUA_ADDRESS: addressSchema,
  AQUA_SWAP_ROUTER_ADDRESS: addressSchema,
  LIMIT_SWAP_ROUTER_ADDRESS: addressSchema,
  WRAPPED_NATIVE_TOKEN_ADDRESS: addressSchema,
  ORDER_CONTROLLER_ADDRESS: addressSchema,
  MONGODB_URI: exports_external.string().min(1),
  MONGODB_DATABASE: exports_external.string().regex(/^[a-zA-Z0-9_-]+$/u),
  SIWE_DOMAIN: exports_external.string().min(1),
  SIWE_URI: exports_external.url(),
  AUTH_ISSUER: authUriSchema2,
  AUTH_RESOURCE: authUriSchema2,
  PASETO_V4_SECRET_KEY: exports_external.string().regex(/^k4\.secret\.[A-Za-z0-9_-]{86}$/u),
  PASETO_V4_PUBLIC_KEYS: exports_external.array(pasetoPublicKeySchema).min(1).refine((keys) => new Set(keys).size === keys.length, "Duplicate PASETO public key"),
  ACCESS_TTL_SECONDS: exports_external.coerce.number().int().min(60).default(900),
  REFRESH_TTL_SECONDS: exports_external.coerce.number().int().min(300).default(2592000),
  RPC_TIMEOUT_MS: exports_external.coerce.number().int().min(100).max(60000).default(1e4),
  HOST: exports_external.string().default("0.0.0.0"),
  PORT: exports_external.coerce.number().int().min(0).max(65535).default(3000),
  CORS_ORIGIN: exports_external.string().default("http://localhost:3000"),
  ACTIVITY_CONFIRMATIONS: exports_external.coerce.number().int().min(0).max(1e4),
  ACTIVITY_MAX_SUBSCRIPTIONS_PER_USER: exports_external.coerce.number().int().min(1).max(1e4).default(100),
  INTENT_AUTHORIZATION_TTL_SECONDS: exports_external.coerce.number().int().min(30).max(900).default(300)
}).strict();
var parsePublicKeys = (value) => {
  if (value === undefined)
    return;
  try {
    return parseStrictJson(value);
  } catch {
    return value;
  }
};
var loadConfiguration = (environment) => {
  const parsed = environmentSchema.parse({
    CHAIN_ID: environment["CHAIN_ID"],
    RPC_URL: environment["RPC_URL"],
    AQUA_ADDRESS: environment["AQUA_ADDRESS"],
    AQUA_SWAP_ROUTER_ADDRESS: environment["AQUA_SWAP_ROUTER_ADDRESS"],
    LIMIT_SWAP_ROUTER_ADDRESS: environment["LIMIT_SWAP_ROUTER_ADDRESS"],
    WRAPPED_NATIVE_TOKEN_ADDRESS: environment["WRAPPED_NATIVE_TOKEN_ADDRESS"],
    ORDER_CONTROLLER_ADDRESS: environment["ORDER_CONTROLLER_ADDRESS"],
    MONGODB_URI: environment["MONGODB_URI"],
    MONGODB_DATABASE: environment["MONGODB_DATABASE"],
    SIWE_DOMAIN: environment["SIWE_DOMAIN"],
    SIWE_URI: environment["SIWE_URI"],
    AUTH_ISSUER: environment["AUTH_ISSUER"],
    AUTH_RESOURCE: environment["AUTH_RESOURCE"],
    PASETO_V4_SECRET_KEY: environment["PASETO_V4_SECRET_KEY"],
    PASETO_V4_PUBLIC_KEYS: parsePublicKeys(environment["PASETO_V4_PUBLIC_KEYS"]),
    ACCESS_TTL_SECONDS: environment["ACCESS_TTL_SECONDS"],
    REFRESH_TTL_SECONDS: environment["REFRESH_TTL_SECONDS"],
    RPC_TIMEOUT_MS: environment["RPC_TIMEOUT_MS"],
    HOST: environment["HOST"],
    PORT: environment["PORT"],
    CORS_ORIGIN: environment["CORS_ORIGIN"],
    ACTIVITY_CONFIRMATIONS: environment["ACTIVITY_CONFIRMATIONS"],
    ACTIVITY_MAX_SUBSCRIPTIONS_PER_USER: environment["ACTIVITY_MAX_SUBSCRIPTIONS_PER_USER"],
    INTENT_AUTHORIZATION_TTL_SECONDS: environment["INTENT_AUTHORIZATION_TTL_SECONDS"]
  });
  return parsed;
};

// apps/api/src/main.ts
var config3 = loadConfiguration(Bun.env);
initializeCubane();
var rpc2 = new JsonRpcClient(new URL(config3.RPC_URL), config3.RPC_TIMEOUT_MS);
var mongo = new import_mongodb2.MongoClient(config3.MONGODB_URI);
await mongo.connect();
var store = new MongoAuthStore(mongo, config3.MONGODB_DATABASE);
await store.initialize();
var auth2 = await AuthService.create({
  domain: config3.SIWE_DOMAIN,
  uri: config3.SIWE_URI,
  chainId: config3.CHAIN_ID,
  issuer: config3.AUTH_ISSUER,
  resource: config3.AUTH_RESOURCE,
  secretKeyPaserk: config3.PASETO_V4_SECRET_KEY,
  publicKeysPaserk: config3.PASETO_V4_PUBLIC_KEYS,
  accessTtlSeconds: config3.ACCESS_TTL_SECONDS,
  refreshTtlSeconds: config3.REFRESH_TTL_SECONDS
}, store, rpc2);
var protocol = new ProtocolService({
  chainId: config3.CHAIN_ID,
  aqua: config3.AQUA_ADDRESS,
  aquaSwapRouter: config3.AQUA_SWAP_ROUTER_ADDRESS,
  limitSwapRouter: config3.LIMIT_SWAP_ROUTER_ADDRESS,
  wrappedNativeToken: config3.WRAPPED_NATIVE_TOKEN_ADDRESS
}, rpc2);
var activityRepository = new MongoActivityRepository(mongo, config3.MONGODB_DATABASE);
await activityRepository.initialize();
var activity2 = new ActivityService(activityRepository, new RpcActivityChain(rpc2), BigInt(config3.ACTIVITY_CONFIRMATIONS), config3.ACTIVITY_MAX_SUBSCRIPTIONS_PER_USER);
var tradingRepository = new MongoTradingRepository(mongo, config3.MONGODB_DATABASE);
await tradingRepository.initialize();
var trading2 = new TradingService(tradingRepository, new AquaProtocolGateway(protocol, rpc2), new IntentAuthorizationService(tradingRepository, rpc2, {
  chainId: config3.CHAIN_ID,
  controller: config3.ORDER_CONTROLLER_ADDRESS,
  validitySeconds: config3.INTENT_AUTHORIZATION_TTL_SECONDS
}), config3.CHAIN_ID);
var configuredContracts = [config3.AQUA_ADDRESS, config3.AQUA_SWAP_ROUTER_ADDRESS, config3.LIMIT_SWAP_ROUTER_ADDRESS, config3.WRAPPED_NATIVE_TOKEN_ADDRESS, config3.ORDER_CONTROLLER_ADDRESS];
var readiness = async () => {
  if (await rpc2.chainId() !== config3.CHAIN_ID)
    return false;
  const codes = await Promise.all(configuredContracts.map((address) => rpc2.getCode(address)));
  return codes.every((code) => code.length > 2);
};
if (!await readiness())
  throw new Error("Startup validation failed: chain or configured contract mismatch");
var serverOptions = createServerOptions({ trading: trading2, auth: auth2, activity: activity2, corsOrigin: config3.CORS_ORIGIN, readiness });
Object.assign(serverOptions, { hostname: config3.HOST, port: config3.PORT });
var server = Bun.serve(serverOptions);
console.log(JSON.stringify({ level: "info", message: "server started", url: server.url.toString(), chainId: config3.CHAIN_ID }));
var shutdown = async () => {
  await server.stop();
  await mongo.close();
};
process.once("SIGTERM", () => {
  shutdown();
});
process.once("SIGINT", () => {
  shutdown();
});
